$debug=0;
if(isset($argv[1]) and $argv[1]!=""){
    $debug=$argv[1];
}

require_once("includes/rutas.php");
require_once("libs/Jos_thread.class.php");

define("VALIDACION",10); //en segundos

$cmd=RUTA_PYTHON." motor/devuelve_posicion_cara.php '".RUTA_PROYECTO."' ".$debug;
echo $cmd;

exit;

$threads=[];
$proc="procesos_panel_control";

$tiempo_inicial = microtime(true);
while(true){

    if(!isset($threads[$proc]) or $threads[$proc]==NULL){
        echo "No existia el proceso..\n";
        
        $threads[$proc]=new Jos_Thread($proc,$cmd,true);
        $threads[$proc]->start();
        
        $tiempo_inicial = microtime(true);
    }

    if((microtime(true) - $tiempo_inicial)>VALIDACION){
        if(!$threads[$proc]->isrunning()){
            $threads[$proc]=new Jos_Thread($proc,$cmd,true);
            $threads[$proc]->start();
        }
        $tiempo_inicial = microtime(true);
    }
    
    sleep(1);
}